SELECT t.id, t.provider_id, t.inbox_visible, t.is_read, t.is_signal, t.effective_ts AS sort_ts, t.created_at, t.updated_at, uh.updated_at AS viewed_at, t.project_id, lmp.subject AS name, lmp.snippet, lmp.is_draft, CASE WHEN $1 THEN TRUE ELSE ( SELECT EXISTS ( SELECT 1 FROM email_messages m_imp JOIN email_message_mailbox_facts mf ON mf.id = m_imp.id WHERE m_imp.thread_id = t.id AND mf.is_present AND NOT mf.in_trash AND mf.provider_is_important ) ) END AS is_important, c.email_address AS sender_email, COALESCE(lmp.from_name, c.name) AS sender_name, c.sfs_photo_url as sender_photo_url, el.macro_id AS owner_id, el.id AS link_id FROM ( -- Step 1: Efficiently find and sort candidate threads SELECT * FROM ( SELECT per_link.* FROM unnest($2) AS links(link_id) CROSS JOIN LATERAL ( SELECT t.id, t.provider_id, t.link_id, t.inbox_visible, t.is_read, t.is_signal, t.project_id, GREATEST(t.latest_inbound_message_ts, t.reminder_returned_at) AS created_at, t.updated_at AS updated_at, GREATEST(t.latest_inbound_message_ts, t.reminder_returned_at) AS effective_ts FROM email_threads t WHERE t.link_id = links.link_id AND t.inbox_visible = TRUE AND (t.latest_inbound_message_ts IS NOT NULL OR t.reminder_returned_at IS NOT NULL) AND t.id = $3 -- Cursor logic AND (($4::timestamptz IS NULL) OR ((GREATEST(t.latest_inbound_message_ts, t.reminder_returned_at), t.id) < ($5::timestamptz, $6::uuid))) ORDER BY effective_ts DESC, id DESC LIMIT $7 ) AS per_link ) AS candidate_threads ORDER BY effective_ts DESC, id DESC LIMIT $8) AS t -- Step 2: For each thread, find its latest message matching the filter CROSS JOIN LATERAL ( SELECT m.subject, m.snippet, m.from_contact_id, m.from_name, m.is_draft FROM email_messages m WHERE m.thread_id = t.id AND EXISTS (SELECT 1 FROM email_message_mailbox_facts mf WHERE mf.id = m.id AND mf.is_present AND NOT mf.in_trash) ORDER BY COALESCE(m.internal_date_ts, m.created_at) DESC, m.id DESC LIMIT 1 ) AS lmp -- Step 3: Join to get the sender's details LEFT JOIN email_contacts c ON lmp.from_contact_id = c.id -- Step 4: Join to get the thread owner's macro user ID JOIN email_links el ON t.link_id = el.id LEFT JOIN email_user_history uh ON uh.thread_id = t.id AND uh.link_id = t.link_id ORDER BY t.effective_ts DESC, t.id DESC
